SELECT json_build_object('has_next', coalesce(bool_or(s1.__rn > $12), false), 'has_prev', false, 'first', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $12))->0, 'last', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $12))->-1, 'n', count(*) FILTER (WHERE s1.__rn <= $12), 'rows', coalesce(json_agg(s1.data ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $12), '[]'::json)) AS data
FROM (
  SELECT json_build_object('id', t0."id") AS data, jsonb_build_array(t0."id") AS __key, row_number() OVER (ORDER BY t0."id" ASC) AS __rn
  FROM "public"."places" t0
  WHERE (NOT (t0."area"::geometry ~= CASE WHEN left($1, 1) = '{' THEN ST_GeomFromGeoJSON($1) ELSE ST_GeomFromEWKT($1) END) AND NOT (t0."area"::geometry &&& CASE WHEN left($2, 1) = '{' THEN ST_GeomFromGeoJSON($2) ELSE ST_GeomFromEWKT($2) END) AND NOT (ST_3DIntersects(t0."area"::geometry, CASE WHEN left($3, 1) = '{' THEN ST_GeomFromGeoJSON($3) ELSE ST_GeomFromEWKT($3) END)) AND NOT (ST_OrderingEquals(t0."area"::geometry, CASE WHEN left($4, 1) = '{' THEN ST_GeomFromGeoJSON($4) ELSE ST_GeomFromEWKT($4) END)) AND t0."location" &&& CASE WHEN left($5, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($5), 4326) ELSE ST_GeomFromEWKT($5) END AND t0."location" = CASE WHEN left($6, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($6), 4326) ELSE ST_GeomFromEWKT($6) END AND ST_3DIntersects(t0."location", CASE WHEN left($7, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($7), 4326) ELSE ST_GeomFromEWKT($7) END) AND ST_OrderingEquals(t0."location", CASE WHEN left($8, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($8), 4326) ELSE ST_GeomFromEWKT($8) END)) AND NOT (t0."area" = (CASE WHEN left($9, 1) = '{' THEN ST_GeomFromGeoJSON($9) ELSE ST_GeomFromEWKT($9) END)::geography) AND t0."location" ~= CASE WHEN left($10, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($10), 4326) ELSE ST_GeomFromEWKT($10) END
  ORDER BY t0."id" ASC
  LIMIT $11
) s1
